__NUXT_JSONP__("/ar/stay", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{details:{slug:"ar",pageTitle:"أماكن الإقامة | Mentor Language Institute",pageDescription:b,title:"أماكن الإقامة",image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:b,types:[{title:"Dormitory",description:["هناك 40 غرفة في المهجع. سيكون هناك الكثير من الفرص للتواصل مع الطلاب الدوليين الآخرين. ننصحك بالإقامة في سكن الطلاب إذا اردت ان توفر مالا."],lists:[" غرفة: خاصة (الفردية)، المشتركة (2 الناس) أو رباعية (4 أشخاص)"," وجبة: لا وجبات [مطبخ مفروشة بالكامل متاح] "," الخصوصية: هناك المزيد من الخصوصية في المهاجع مما كانت عليه في منزل، ومع ذلك، هناك بعض قواعد المهجع.","الانتقال إلى المدرسة: الانتقال إلى المدرسة: حوالي 20 دقيقة سيرا على الأقدام أو الحافلة."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"أسعار السكن الطلابي",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E إذا كان عمره أقل من 18 عامًا ، فسيكون الإيجار أعلى بنسبة 10٪ تقريبًا من سعر الشخص الأكبر من 18 عامًا.",thead:[c,d,"Shared (2 people)","Quad (4 people)"],tbody:[[e,a,a,a],[f,"$550","$410",a],[g,"$1,100","$820","$600"],[h,"$1,650","$1,230","$900"],[i,"$2,200","$1,640","$1,200"],[j,"$4,160","$2,960","$2,160"],[k,"$6,240","$4,440","$3,240"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out."]}]},{title:"سكن مع عائلة امريكية",description:["الطلاب الذين يختارون العيش مع عائلة امريكية الإقامة يبحثون عن آمنة، والترحيب، وجو مريح حيث يمكنهم ممارسة مهاراتهم في اللغة الإنجليزية. كما انها فرصة للتعرف على العادات والتقاليد الامريكية والقيم العائلية."],lists:["الغرفة: خاص (فردي)","وجبة: 2 وجبات يوميا (الإفطار والعشاء)","الخصوصية: هناك بعض قواعد المنزل اعتمادا على الأسرة المضيفة.","تخفيف: 30- 45 دقيقة في المتوسط ​​بالحافلة"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"أسعار الإقامة",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E إذا كان عمره أقل من 18 عامًا ، فسيكون الإيجار أعلى بنسبة 10٪ تقريبًا من سعر الشخص الأكبر من 18 عامًا.",thead:[c,d,"Shared***"],tbody:[[e,a,a],[f,"$436","$384"],[g,"$872","$768"],[h,"$1,308","$1,152"],[i,"$1,744","$1,536"],[j,"$3,160","$2,904"],[k,"$4,740","$4,356"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out.\u003Cbr \u002F\u003E***If you request a homestay shared room, \u003Cspan class=\"rmarker\"\u003Eyou must apply with another person.\u003C\u002Fspan\u003E"]}]}],comments:{title:"تعليقات من موظفينا",description:["ليس من السهل العثور على مكان للإقامة عند وصولك لأول مرة إلى الولايات المتحدة، \u003Cbr \u002F\u003Eخاصة للطلاب الأجانب الذين ليس لديهم رقم الضمان الاجتماعي (SSN) والتاريخ الائتماني. \u003Cbr \u002F\u003Eتتطلب معظم الأماكن كلا من رقم التأمين الاجتماعي (SSN) والتاريخ الائتماني لاستئجار مكان. \u003Cbr \u002F\u003Eولذلك، فإننا نوصي لك البقاء في أماكن الإقامة لدينا"]},dir:"\u002Fstay",path:"\u002Fstay\u002Far",extension:".json",createdAt:"2026-10-22T16:31:31.067Z",updatedAt:"2025-05-26T12:06:27.917Z"}}],fetch:{},mutations:void 0}}("$300","يمكن للطلاب اختيار أماكن الإقامة المنزلية أو الإقامة المشتركة.","","Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));